// SigRewrite-Core - AST rewrite demo
var AST = { type: "Call", name: "oldApi", args: ["x"] };
var rules = [
  { match: function(n) { return n.type === "Call" && n.name === "oldApi"; },
    rewrite: function(n) { return { type: "Call", name: "newApi", args: n.args.concat(["opts"]) }; } }
];
function applyRules(node) { rules.forEach(function(r) { if (r.match(node)) node = r.rewrite(node); }); return node; }
console.log("Engine: SigRewrite | Rewrites: Sig AST");
console.log("Before: " + JSON.stringify(AST));
console.log("After:  " + JSON.stringify(applyRules(AST)));
console.log("Rewrite applied -> PASS");

